  constructor() {
    /** @type {Map<number, TrieNode>} Map from code point to child node */
    this.children = new Map();

    /** @type {unknown} The value stored at this node, if any */
    this.value = undefined;

    /** @type {boolean} Whether this node represents a stored word */
    this.hasValue = false;

    /** @type {number} Count of stored words in this subtree */
    this.count = 0;
  }
}

