    if (typeof word !== 'string') throw new TypeError('word must be a string');

    // Walk/create path through trie
    const chars = [...word]; // Split by Unicode code points
    let node = this.#root;

    for (const char of chars) {
      const codePoint = char.codePointAt(0);
      if (!node.children.has(codePoint)) {
        node.children.set(codePoint, new TrieNode());
      }
      node = node.children.get(codePoint);
    }

    // Store the previous value
    const previous = node.hasValue ? node.value : undefined;
    const isNew = !node.hasValue;

    // Set the value
    node.value = value;
    if (isNew) {
      node.hasValue = true;
      this.#size++;

      // Increment counts from root to this node
      let current = this.#root;
      current.count++;
      for (const char of chars) {
        const codePoint = char.codePointAt(0);
        current = current.children.get(codePoint);
        current.count++;
      }
    }

    return previous;
  }

