    const chars = [...word];
    let node = this.#root;
    const path = [this.#root];

    // Walk to the node for this word
    for (const char of chars) {
      const codePoint = char.codePointAt(0);
      if (!node.children.has(codePoint)) return false;
      node = node.children.get(codePoint);
      path.push(node);
